begin;
grant insert,select on pg_temp.test_assertions to sivirinia_worker;
insert into auth.users(id,email,email_confirmed_at) values
('71000000-0000-0000-0000-000000000001','pipeline-owner@example.test',now()),
('71000000-0000-0000-0000-000000000002','pipeline-other@example.test',now()),
('71000000-0000-0000-0000-000000000003','pipeline-viewer@example.test',now());
insert into public.organizations(id,name) values
('72000000-0000-0000-0000-000000000001','Pipeline A'),('72000000-0000-0000-0000-000000000002','Pipeline B');
insert into public.organization_members(organization_id,user_id,role) values
('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','owner'),
('72000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002','owner'),
('72000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000003','viewer');
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select set_config('test.task',public.enqueue_document('72000000-0000-0000-0000-000000000001','Política v1','politica.txt','text',encode(convert_to('Reembolso em sete dias.','UTF8'),'base64'))::text,true);
select pg_temp.assert_eq((select status from public.document_tasks where id=current_setting('test.task')::uuid),'queued','Admissão persiste tarefa sem indexar sincronamente');
select pg_temp.assert_eq((select count(*)::int from public.knowledge_sources where organization_id='72000000-0000-0000-0000-000000000001'),0,'Tarefa não se apresenta como fonte indexada');
select pg_temp.assert_throws($$select lease_token from public.document_tasks$$,'42501',null,'Lease não é exposto aos usuários');
select pg_temp.assert_throws($$select * from sivirinia_internal.document_inputs$$,'42501',null,'Payload privado não pode ser lido diretamente');
select pg_temp.assert_throws($$select sivirinia_internal.claim_document()$$,'42501',null,'Usuário não pode se tornar worker');
select pg_temp.assert_throws($$select public.enqueue_document('72000000-0000-0000-0000-000000000001','Duplicado','x.txt','text',encode(convert_to('Reembolso em sete dias.','UTF8'),'base64'))$$,'P0001','Documento duplicado','Duplicata pendente é rejeitada');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_eq((select count(*)::int from public.document_tasks),0,'Outro tenant não vê tarefa');
select pg_temp.assert_throws($$select public.enqueue_document('72000000-0000-0000-0000-000000000001','Invasão','x.txt','text','eA==')$$,'P0001','Sem permissão','Outro tenant não enfileira documento');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_throws($$select public.enqueue_document('72000000-0000-0000-0000-000000000001','Viewer','x.txt','text','eA==')$$,'P0001','Sem permissão','Leitor não enfileira documento');
reset role;
set local role sivirinia_worker;
select pg_temp.assert_throws($$select * from public.document_tasks$$,'42501',null,'Worker não lê diretamente tarefas');
select pg_temp.assert_throws($$select * from auth.users$$,'42501',null,'Worker não lê contas Auth');
select set_config('test.claim',sivirinia_internal.claim_document()::text,true);
select pg_temp.assert_eq(current_setting('test.claim')::jsonb->>'id',current_setting('test.task'),'Worker reivindica a tarefa real');
select pg_temp.assert_eq(sivirinia_internal.claim_document(),null::jsonb,'Lease impede execução concorrente no tenant');
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.task')::uuid,gen_random_uuid(),'[{"text":"Reembolso em sete dias.","page":null}]','text','[{"content":"Reembolso em sete dias.","page":null}]',repeat('a',64))$$,'P0001','Lease inválido','Token incorreto não pode concluir');
select set_config('test.source',sivirinia_internal.finish_document(current_setting('test.task')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,'[{"text":"Reembolso em sete dias.","page":null}]','text','[{"content":"Reembolso em sete dias.","page":null}]',repeat('a',64))::text,true);
select pg_temp.assert_eq(sivirinia_internal.finish_document(current_setting('test.task')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,'[]','text','[]',repeat('a',64))::text,current_setting('test.source'),'Conclusão repetida é idempotente');
reset role;
select pg_temp.assert_eq((select count(*)::int from sivirinia_internal.document_inputs where task_id=current_setting('test.task')::uuid),0,'Payload temporário removido após snapshot');
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_eq((select status from public.document_tasks where id=current_setting('test.task')::uuid),'complete','Tarefa concluída é observável');
select pg_temp.assert_eq(convert_from(decode(public.get_document_original('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,1)->>'base64','base64'),'UTF8'),'Reembolso em sete dias.','Download preserva bytes do original');
select pg_temp.assert_eq(public.get_document_version('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,1)->0->>'text','Reembolso em sete dias.','Snapshot preserva texto integral');
select pg_temp.assert_throws($$select original from public.document_snapshots$$,'42501',null,'Bytes não têm SELECT amplo');
select set_config('test.task2',public.enqueue_document('72000000-0000-0000-0000-000000000001','Política v2','politica.txt','text',encode(convert_to('Reembolso em quatorze dias.','UTF8'),'base64'),current_setting('test.source')::uuid)::text,true);
reset role;
set local role sivirinia_worker;
select set_config('test.claim2',sivirinia_internal.claim_document()::text,true);
select sivirinia_internal.finish_document(current_setting('test.task2')::uuid,(current_setting('test.claim2')::jsonb->>'token')::uuid,'[{"text":"Reembolso em quatorze dias.","page":null}]','text','[{"content":"Reembolso em quatorze dias.","page":null}]',repeat('b',64));
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_eq((select version from public.knowledge_sources where id=current_setting('test.source')::uuid),2,'Atualização incrementa versão');
select pg_temp.assert_eq((select count(*)::int from public.document_snapshots where source_id=current_setting('test.source')::uuid),2,'Ambas versões completas são preservadas');
select pg_temp.assert_eq(public.get_document_version('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,1)->0->>'text','Reembolso em sete dias.','Texto antigo permanece recuperável');
select pg_temp.assert_eq((select content from public.document_chunks where source_id=current_setting('test.source')::uuid),'Reembolso em quatorze dias.','Busca usa somente versão atual');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_eq((select count(*)::int from public.document_snapshots),0,'Snapshots isolados entre empresas');
select pg_temp.assert_throws($$select public.get_document_original('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,1)$$,'P0001','Sem permissão','Download bloqueia outro tenant');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select public.set_source_roles('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,array['editor']::public.member_role[]);
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_throws($$select public.get_document_version('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid,1)$$,'P0001','Sem permissão','ACL atual também protege versões antigas');
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select set_config('test.failed',public.enqueue_document('72000000-0000-0000-0000-000000000001','Falha recuperável','falha.txt','text','eA==')::text,true);
reset role;
set local role sivirinia_worker;
select set_config('test.failureclaim',sivirinia_internal.claim_document()::text,true);
select sivirinia_internal.fail_document(current_setting('test.failed')::uuid,(current_setting('test.failureclaim')::jsonb->>'token')::uuid,'internal_error',true);
reset role;
select pg_temp.assert_eq((select status from public.document_tasks where id=current_setting('test.failed')::uuid),'retry','Falha transitória agenda retentativa');
select pg_temp.assert_true((select available_at>now() from public.document_tasks where id=current_setting('test.failed')::uuid),'Backoff não executa nova tentativa imediatamente');
update public.document_tasks set available_at=now() where id=current_setting('test.failed')::uuid;
set local role sivirinia_worker;
select set_config('test.failureclaim2',sivirinia_internal.claim_document()::text,true);
select pg_temp.assert_ne(current_setting('test.failureclaim2')::jsonb->>'token',current_setting('test.failureclaim')::jsonb->>'token','Cada tentativa rotaciona token de lease');
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.failed')::uuid,(current_setting('test.failureclaim')::jsonb->>'token')::uuid,'[]','text','[]',repeat('c',64))$$,'P0001','Lease inválido','Worker antigo não pode concluir tentativa nova');
select sivirinia_internal.fail_document(current_setting('test.failed')::uuid,(current_setting('test.failureclaim2')::jsonb->>'token')::uuid,'worker_timeout',true);
reset role;
update public.document_tasks set available_at=now() where id=current_setting('test.failed')::uuid;
set local role sivirinia_worker;
select set_config('test.failureclaim3',sivirinia_internal.claim_document()::text,true);
select sivirinia_internal.fail_document(current_setting('test.failed')::uuid,(current_setting('test.failureclaim3')::jsonb->>'token')::uuid,'worker_timeout',true);
reset role;
select pg_temp.assert_eq((select attempts from public.document_tasks where id=current_setting('test.failed')::uuid),3,'Orçamento de tentativas é limitado a três');
select pg_temp.assert_eq((select status from public.document_tasks where id=current_setting('test.failed')::uuid),'failed','Falha final não continua em loop');
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_throws($$select public.retry_document_task('72000000-0000-0000-0000-000000000001',current_setting('test.failed')::uuid)$$,'P0001','Documento não permite nova tentativa; corrija e envie novamente','Retry manual não burla orçamento');
select public.cancel_document_task('72000000-0000-0000-0000-000000000001',current_setting('test.failed')::uuid);
reset role;
select pg_temp.assert_eq((select count(*)::int from sivirinia_internal.document_inputs where task_id=current_setting('test.failed')::uuid),0,'Descartar falha apaga original pendente');
set local role authenticated;
select set_config('test.cancel',public.enqueue_document('72000000-0000-0000-0000-000000000001','Cancelar','cancelar.txt','text','eQ==')::text,true);
reset role;
set local role sivirinia_worker;
select set_config('test.cancelclaim',sivirinia_internal.claim_document()::text,true);
set local role authenticated;
select public.cancel_document_task('72000000-0000-0000-0000-000000000001',current_setting('test.cancel')::uuid);
set local role sivirinia_worker;
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.cancel')::uuid,(current_setting('test.cancelclaim')::jsonb->>'token')::uuid,'[]','text','[]',repeat('d',64))$$,'P0001','Lease inválido','Cancelamento invalida worker ainda em execução');
reset role;
-- Additional recovery and resource-limit checks operate only on rollback fixtures.
update public.document_tasks set created_at=now()-interval '2 minutes' where organization_id='72000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-0000-0000-000000000001',true);
select set_config('test.expired',public.enqueue_document('72000000-0000-0000-0000-000000000001','Recuperar lease','recuperar.txt','text','eg==',current_setting('test.source')::uuid)::text,true);
reset role;
set local role sivirinia_worker;
select set_config('test.expiredclaim',sivirinia_internal.claim_document()::text,true);
reset role;
update public.document_tasks set lease_until=now()-interval '1 second' where id=current_setting('test.expired')::uuid;
set local role sivirinia_worker;
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.expired')::uuid,(current_setting('test.expiredclaim')::jsonb->>'token')::uuid,'[]','text','[]',repeat('e',64))$$,'P0001','Lease expirado','Lease vencido não pode concluir mesmo antes de ser reivindicado');
select set_config('test.recovered',sivirinia_internal.claim_document()::text,true);
select pg_temp.assert_eq(current_setting('test.recovered')::jsonb->>'id',current_setting('test.expired'),'Tarefa abandonada é retomada');
select pg_temp.assert_ne(current_setting('test.expiredclaim')::jsonb->>'token',current_setting('test.recovered')::jsonb->>'token','Recuperação invalida token anterior');
reset role;
select pg_temp.assert_eq((select attempts from public.document_tasks where id=current_setting('test.expired')::uuid),2,'Recuperação consome tentativa');
update public.organization_members set role='viewer' where organization_id='72000000-0000-0000-0000-000000000001' and user_id='71000000-0000-0000-0000-000000000001';
set local role sivirinia_worker;
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.expired')::uuid,(current_setting('test.recovered')::jsonb->>'token')::uuid,'[]','text','[]',repeat('e',64))$$,'P0001','Sem permissão','Revogação durante fila impede commit do worker');
reset role;
update public.organization_members set role='owner' where organization_id='72000000-0000-0000-0000-000000000001' and user_id='71000000-0000-0000-0000-000000000001';
update public.knowledge_sources set version=version+1 where id=current_setting('test.source')::uuid;
set local role sivirinia_worker;
select pg_temp.assert_throws($$select sivirinia_internal.finish_document(current_setting('test.expired')::uuid,(current_setting('test.recovered')::jsonb->>'token')::uuid,'[]','text','[]',repeat('e',64))$$,'P0001','Fonte alterada ou sem permissão','Versão concorrente não é sobrescrita');
reset role;
update public.plans set storage_limit_bytes=1 where id=(select plan_id from public.organizations where id='72000000-0000-0000-0000-000000000001');
set local role authenticated;
select pg_temp.assert_throws($$select public.enqueue_document('72000000-0000-0000-0000-000000000001','Sem espaço','cheio.txt','text','dGVzdGU=')$$,'P0001','Limite de armazenamento privado atingido','Cota inclui originais de versões históricas');
set local role authenticated;
select public.delete_source('72000000-0000-0000-0000-000000000001',current_setting('test.source')::uuid);
reset role;
select pg_temp.assert_eq((select count(*)::int from public.document_snapshots where source_id=current_setting('test.source')::uuid),0,'Excluir fonte remove todos os originais e snapshots');
select pg_temp.assert_eq((select count(*)::int from public.document_chunks where source_id=current_setting('test.source')::uuid),0,'Excluir fonte remove todos os índices');
set local role anon;
select pg_temp.assert_throws($$select public.get_document_original('72000000-0000-0000-0000-000000000001',gen_random_uuid(),1)$$,'42501',null,'Anônimo não executa download de original');
reset role;
select 'ASSERTIONS='||count(*) from pg_temp.test_assertions;
rollback;
